    boundary_variants: List[Dict[str, Any]] = []
    if _nonempty(merged.get("timetable_low")):
        variant_low = json.loads(json.dumps(base_body))
        variant_low["timetable"] = merged["timetable_low"]
        boundary_variants.append(variant_low)
    if _nonempty(merged.get("timetable_high")):
        variant_high = json.loads(json.dumps(base_body))
